<?php
require_once __DIR__.'/../payroll/config.php';$salary=null;if(pay_ready($pdo)){$salaryQuery=$pdo->prepare('SELECT monthly_gross,annual_ctc,effective_from FROM hr_salary_assignments WHERE employee_id=? AND effective_from<=? AND (effective_to IS NULL OR effective_to>=?) ORDER BY effective_from DESC LIMIT 1');$salaryQuery->execute([$owner,$today,$today]);$salary=$salaryQuery->fetch(PDO::FETCH_ASSOC);}
$filesQuery=$pdo->prepare("SELECT f.id,f.filename,r.title,r.status FROM hr_files f JOIN hr_records r ON r.id=f.record_id WHERE r.employee_id=? AND r.module='documents' ORDER BY f.id DESC LIMIT 5");$filesQuery->execute([$owner]);$submittedFiles=$filesQuery->fetchAll(PDO::FETCH_ASSOC);
?>
<section class="panel"><span class="ess-card-icon" aria-hidden="true">₹</span><h2>Salary & payslips</h2><?php if($salary):?><dl class="ess-details"><div><dt>Monthly gross</dt><dd>₹<?=number_format($salary['monthly_gross']/100,2)?></dd></div><div><dt>Annual CTC</dt><dd>₹<?=number_format($salary['annual_ctc']/100,2)?></dd></div><div><dt>Effective from</dt><dd><?=h($salary['effective_from'])?></dd></div></dl><?php else:?><p>No effective salary assignment is available.</p><?php endif;?><a class="ess-text-link" href="?page=my_salary">View salary details →</a><a class="ess-text-link" href="payroll-slip.php">Published payslips →</a></section>
<section class="panel"><span class="ess-card-icon" aria-hidden="true">▤</span><h2>My submitted documents</h2><?php if(!$submittedFiles):?><p>No documents submitted yet.</p><?php else:?><ul class="ess-document-list"><?php foreach($submittedFiles as $file):?><li><a href="document.php?id=<?=(int)$file['id']?>"><?=h($file['filename'])?></a><small><?=h($file['title'])?> · <?=h($file['status'])?></small></li><?php endforeach;?></ul><?php endif;?><a class="ess-text-link" href="?page=documents">View all documents →</a></section>
